/* SchwiizMC — Foto-Überraschung. Alles läuft lokal im Browser. */
(() => {
  // ---------- Einstellungen ----------
  const TARGET_SRC = "data:image/png;base64,";
  const N = 256, NN = N * N;          // 256×256 Pixel
  const SC = 2, W = N * SC;           // Anzeige/Video: 512×512
  const HOLD0 = 1.0, FLY = 8.0, HOLD1 = 1.5, TOTAL = HOLD0 + FLY + HOLD1;
  const W_DIST = 0.6;                 // Vorliebe für kurze Wege
  const LAMBDA = 0.2;                 // Anteil relative Helligkeit
  const BG_WEIGHT = 0.15;             // Gewicht des Hintergrunds (Gesicht = 1)
  const ITER = 16000000, CHUNK = 500000;
  const BG = 0xff20100a;              // Hintergrund (#0a1020, wie die Seite)
  const TARGET_BG = [10, 16, 32];     // Farbe hinter dem Logo

  const $ = id => document.getElementById(id);
  const modal = $('morph-modal'), canvas = $('morph-canvas');
  const ctx = canvas.getContext('2d');
  const fileInput = $('morph-file'), pickBtn = $('morph-pick');
  const replayBtn = $('morph-replay'), saveBtn = $('morph-save'), shareBtn = $('morph-share');
  const progress = $('morph-progress'), bar = $('morph-bar'), statusEl = $('morph-status');

  const frame = ctx.createImageData(W, W);
  const buf = new Uint32Array(frame.data.buffer);

  let targetImg = null, T = null, anim = null;
  let runId = 0, rafId = 0, recorder = null;
  let videoBlob = null, videoExt = 'webm', ready = false;

  // ---------- Hilfsfunktionen ----------
  const setStatus = t => { statusEl.textContent = t; };
  const nextFrame = () => new Promise(r => requestAnimationFrame(() => r()));
  let seed = 0x9e3779b9;
  const rand = () => { seed ^= seed << 13; seed ^= seed >>> 17; seed ^= seed << 5; return seed >>> 0; };
  const rnd01 = () => rand() / 4294967296;

  function loadImage(src) {
    return new Promise((res, rej) => {
      const im = new Image();
      im.onload = () => res(im);
      im.onerror = () => rej(new Error('Bild konnte nicht geladen werden'));
      im.src = src;
    });
  }

  // Bild mittig quadratisch zuschneiden und auf 256×256 verkleinern
  function readPixels(im, autoBright, isTarget) {
    // Ganzes Foto nutzen, im echten Seitenverhältnis: Raster gw×gh mit ca. 65'536 Pixeln.
    // Extrem breite/hohe Fotos (mehr als 8:1) werden in der Mitte auf 8:1 zugeschnitten.
    let sx = 0, sy = 0, sw = im.naturalWidth, sh = im.naturalHeight;
    if (sw / sh > 8) { const nw = sh * 8; sx = (sw - nw) / 2; sw = nw; }
    if (sh / sw > 8) { const nh = sw * 8; sy = (sh - nh) / 2; sh = nh; }
    const gw = Math.max(1, Math.round(Math.sqrt(NN * sw / sh)));
    const gh = Math.max(1, Math.floor(NN / gw)), total = gw * gh;
    const c = document.createElement('canvas');
    c.width = gw; c.height = gh;
    const g = c.getContext('2d', { willReadFrequently: true });
    g.imageSmoothingEnabled = true;
    g.imageSmoothingQuality = 'high';
    g.drawImage(im, sx, sy, sw, sh, 0, 0, gw, gh);
    const img = g.getImageData(0, 0, gw, gh), d = img.data;
    if (autoBright) {
      // Sehr dunkle Fotos aufhellen, damit man im Ergebnis etwas erkennt
      const hist = new Uint32Array(256);
      for (let i = 0; i < total; i++) hist[Math.round(0.299 * d[i * 4] + 0.587 * d[i * 4 + 1] + 0.114 * d[i * 4 + 2])]++;
      const pct = q => { let v = 0, acc = 0; while (v < 255 && acc + hist[v] < total * q) acc += hist[v++]; return v; };
      const lo = pct(0.005), hi = Math.max(pct(0.995), lo + 1), med = pct(0.5);
      // 1) Kontrast strecken (max. 3-fach), 2) wenn immer noch sehr dunkel: aufhellen
      const gain = (lo > 8 || hi < 235) ? Math.min(3, 255 / (hi - lo)) : 1;
      const off = gain > 1 ? lo : 0;
      const med2 = Math.max(1, (med - off) * gain);
      const gamma = med2 < 45 ? Math.max(0.4, Math.log(90 / 255) / Math.log(med2 / 255)) : 1;
      if (gain > 1 || gamma < 1) {
        const lut = new Uint8ClampedArray(256);
        for (let v = 0; v < 256; v++) {
          const x = Math.min(1, Math.max(0, (v - off) * gain / 255));
          lut[v] = Math.round(255 * Math.pow(x, gamma));
        }
        for (let i = 0; i < d.length; i += 4) { d[i] = lut[d[i]]; d[i + 1] = lut[d[i + 1]]; d[i + 2] = lut[d[i + 2]]; }
        g.putImageData(img, 0, 0);
      }
    }
    // Genau 65'536 Pixel: das Raster hat höchstens so viele, die paar fehlenden
    // werden mit Kopien zufälliger Rasterpixel aufgefüllt (liegen deckungsgleich
    // darunter -> keine Löcher, keine Punkte, keine Streifen)
    const scale = N / Math.max(gw, gh);
    const offX = (N - gw * scale) / 2, offY = (N - gh * scale) / 2;
    const r = new Float32Array(NN), gr = new Float32Array(NN), b = new Float32Array(NN);
    const x = new Float32Array(NN), y = new Float32Array(NN), alpha = new Float32Array(NN);
    for (let j = 0; j < NN; j++) {
      const k = j < total ? j : Math.floor(rnd01() * total);
      const al = d[k * 4 + 3] / 255, bgc = isTarget ? TARGET_BG : [0, 0, 0];
      r[j] = d[k * 4] * al + bgc[0] * (1 - al);
      gr[j] = d[k * 4 + 1] * al + bgc[1] * (1 - al);
      b[j] = d[k * 4 + 2] * al + bgc[2] * (1 - al);
      alpha[j] = al;
      x[j] = offX + (k % gw) * scale; y[j] = offY + Math.floor(k / gw) * scale;
    }
    return { r, g: gr, b, x, y, alpha, canvas: c };
  }

  function showImage(src) {
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = '#0a1020';
    ctx.fillRect(0, 0, W, W);
    const k = W / Math.max(src.width, src.height);
    ctx.drawImage(src, (W - src.width * k) / 2, (W - src.height * k) / 2, src.width * k, src.height * k);
  }

  // ---------- Zuordnung: welcher Pixel landet wo ----------
  async function computeAssignment(S, myRun) {
    const ls = new Float32Array(NN), lt = new Float32Array(NN);
    for (let i = 0; i < NN; i++) {
      ls[i] = 0.299 * S.r[i] + 0.587 * S.g[i] + 0.114 * S.b[i];
      lt[i] = 0.299 * T.r[i] + 0.587 * T.g[i] + 0.114 * T.b[i];
    }
    const is = new Uint32Array(NN), it = new Uint32Array(NN);
    for (let i = 0; i < NN; i++) { is[i] = i; it[i] = i; }
    is.sort((a, b) => ls[a] - ls[b]);
    it.sort((a, b) => lt[a] - lt[b]);
    const assign = new Int32Array(NN);       // assign[Zielposition] = Quellpixel
    for (let k = 0; k < NN; k++) assign[it[k]] = is[k];

    // Helligkeit als Rang (0–255): das hellste Viertel des Fotos zählt als "hell",
    // egal ob das Foto insgesamt dunkel oder hell ist -> immer voller Kontrast
    const rankOf = (lum) => {
      const hist = new Uint32Array(256), out = new Float32Array(NN), val = new Float32Array(256);
      for (let i = 0; i < NN; i++) hist[Math.min(255, Math.round(lum[i]))]++;
      let acc = 0;
      for (let v = 0; v < 256; v++) { val[v] = (acc + hist[v] / 2) / NN * 255; acc += hist[v]; }
      for (let i = 0; i < NN; i++) out[i] = val[Math.min(255, Math.round(lum[i]))];
      return out;
    };
    const Rs = rankOf(ls), Rt = rankOf(lt);
    // Gewicht: Gesicht/Hut zählt voll, weisser Hintergrund nur wenig
    // -> passende Farben (z.B. Haut) landen zuerst im Gesicht
    const Wt = new Float32Array(NN);
    for (let i = 0; i < NN; i++) Wt[i] = T.alpha[i] < 0.5 ? BG_WEIGHT : 1;
    const Sr = S.r, Sg = S.g, Sb = S.b, Tr = T.r, Tg = T.g, Tb = T.b;
    const Sx = S.x, Sy = S.y;
    const X = new Float32Array(NN), Y = new Float32Array(NN);
    for (let i = 0; i < NN; i++) { X[i] = i & (N - 1); Y[i] = i >> 8; }
    // Kosten: echte Farbe (so nah am Original wie möglich)
    //       + etwas relative Helligkeit (damit auch dunkle Fotos Kontrast haben)
    //       + kleine Vorliebe für kurze Wege
    const cost = (s, p) => {
      const dr = Sr[s] - Tr[p], dg = Sg[s] - Tg[p], db = Sb[s] - Tb[p], dl = Rs[s] - Rt[p];
      const dx = Sx[s] - X[p], dy = Sy[s] - Y[p];
      return Wt[p] * (dr * dr + dg * dg + db * db + LAMBDA * dl * dl) + W_DIST * (dx * dx + dy * dy);
    };
    const MASK = NN - 1;

    for (let done = 0; done < ITER; done += CHUNK) {
      for (let k = 0; k < CHUNK; k++) {
        const r1 = rand();
        const a = r1 & MASK;
        let b;
        if (r1 & 0x80000000) {
          // Tauschpartner in der Nähe (ungefähr normalverteilt, ±25 px)
          const r2 = rand(), r3 = rand();
          const gx = ((r2 & 255) + ((r2 >>> 8) & 255) + ((r2 >>> 16) & 255) - 382.5) * 0.196;
          const gy = ((r3 & 255) + ((r3 >>> 8) & 255) + ((r3 >>> 16) & 255) - 382.5) * 0.196;
          let bx = (a & (N - 1)) + (gx | 0), by = (a >> 8) + (gy | 0);
          bx = bx < 0 ? 0 : bx >= N ? N - 1 : bx;
          by = by < 0 ? 0 : by >= N ? N - 1 : by;
          b = (by << 8) | bx;
        } else {
          b = rand() & MASK;
        }
        if (a === b) continue;
        const sa = assign[a], sb = assign[b];
        if (cost(sa, a) + cost(sb, b) > cost(sb, a) + cost(sa, b)) { assign[a] = sb; assign[b] = sa; }
      }
      const pct = Math.round(((done + CHUNK) / ITER) * 100);
      bar.style.width = pct + '%';
      setStatus('⏳ Foto wird verarbeitet … ' + pct + ' %');
      await nextFrame();
      if (myRun !== runId) return null;
    }
    return assign;
  }

  // ---------- Animation vorbereiten ----------
  function prepareAnim(S, assign) {
    const a = {
      x0: new Float32Array(NN), y0: new Float32Array(NN),
      dx: new Float32Array(NN), dy: new Float32Array(NN),
      px: new Float32Array(NN), py: new Float32Array(NN),
      amp: new Float32Array(NN), wob: new Float32Array(NN),
      delay: new Float32Array(NN), col: new Uint32Array(NN)
    };
    for (let p = 0; p < NN; p++) {
      const s = assign[p];
      const x0 = S.x[s], y0 = S.y[s], x1 = p % N, y1 = (p / N) | 0;
      const dx = x1 - x0, dy = y1 - y0, L = Math.hypot(dx, dy) + 1e-6;
      a.x0[p] = x0; a.y0[p] = y0; a.dx[p] = dx; a.dy[p] = dy;
      a.px[p] = -dy / L; a.py[p] = dx / L;                    // seitliche Richtung
      a.amp[p] = (rnd01() * 2 - 1) * Math.min(L * 0.12, 8);   // max. ~8 px pendeln
      a.wob[p] = 1 + rnd01() * 1.5;
      a.delay[p] = rnd01() * 0.15;
      a.col[p] = (0xff000000 | (Math.round(S.b[s]) << 16) | (Math.round(S.g[s]) << 8) | Math.round(S.r[s])) >>> 0;
    }
    return a;
  }

  // Ein Bild der Animation in einen Pixelpuffer zeichnen
  function renderInto(time, b) {
    const A = anim;
    let g = (time - HOLD0) / FLY;
    g = g < 0 ? 0 : g > 1 ? 1 : g;
    b.fill(BG);
    const PI = Math.PI, TWO_PI = 2 * Math.PI, MAX = W - SC;
    for (let i = 0; i < NN; i++) {
      let t = (g - A.delay[i]) / 0.85;
      t = t < 0 ? 0 : t > 1 ? 1 : t;
      t = t * t * (3 - 2 * t);
      const side = A.amp[i] * Math.sin(PI * t) * Math.sin(TWO_PI * A.wob[i] * t);
      let xi = ((A.x0[i] + A.dx[i] * t + A.px[i] * side) * SC) | 0;
      let yi = ((A.y0[i] + A.dy[i] * t + A.py[i] * side) * SC) | 0;
      xi = xi < 0 ? 0 : xi > MAX ? MAX : xi;
      yi = yi < 0 ? 0 : yi > MAX ? MAX : yi;
      const o = yi * W + xi, c = A.col[i];
      b[o] = c; b[o + 1] = c; b[o + W] = c; b[o + W + 1] = c;
    }
  }

  function drawFrame(time) {
    renderInto(time, buf);
    ctx.putImageData(frame, 0, 0);
  }

  // ---------- Video: MP4 mit fester Bitrate (WebCodecs) ----------
  const FPS = 30, NFRAMES = Math.round(TOTAL * FPS);
  const BITRATE = 2500000;            // Start: 2,5 Mbit/s
  const MAX_BYTES = 4900000, GOAL_BYTES = 4300000;   // Video max. ~5 MB
  const encCanvas = document.createElement('canvas');
  encCanvas.width = encCanvas.height = W;
  const encCtx = encCanvas.getContext('2d');
  const encFrame = encCtx.createImageData(W, W);
  const encBuf = new Uint32Array(encFrame.data.buffer);
  let job = null;

  async function pickEncoderConfig() {
    if (!window.VideoEncoder || !window.VideoFrame || !window.Mp4Muxer) return null;
    const base = { codec: 'avc1.42001f', width: W, height: W, bitrate: BITRATE, framerate: FPS, avc: { format: 'avc' } };
    for (const mode of ['constant', 'variable']) {
      const cfg = Object.assign({}, base, { bitrateMode: mode });
      try { const r = await VideoEncoder.isConfigSupported(cfg); if (r.supported) return cfg; } catch (e) {}
    }
    try { const r = await VideoEncoder.isConfigSupported(base); if (r.supported) return base; } catch (e) {}
    return null;
  }

  function createVideoJob(cfg) {
    const size = cfg.width;
    let src = encCanvas;
    if (size !== W) {                  // kleinere Videoauflösung als Notlösung
      src = document.createElement('canvas');
      src.width = src.height = size;
    }
    const srcCtx = src.getContext('2d');
    const muxer = new Mp4Muxer.Muxer({
      target: new Mp4Muxer.ArrayBufferTarget(),
      video: { codec: 'avc', width: size, height: size, frameRate: FPS },
      fastStart: 'in-memory'
    });
    let failed = false, i = 0;
    const enc = new VideoEncoder({
      output: (chunk, meta) => { try { muxer.addVideoChunk(chunk, meta); } catch (e) { failed = true; } },
      error: () => { failed = true; }
    });
    try { enc.configure(cfg); } catch (e) { return null; }
    const pause = () => new Promise(r => setTimeout(r, 0));
    return {
      step() {
        if (failed || i >= NFRAMES || enc.encodeQueueSize > 4) return;
        renderInto(i / FPS, encBuf);
        encCtx.putImageData(encFrame, 0, 0);
        if (src !== encCanvas) {
          srcCtx.imageSmoothingEnabled = true;
          srcCtx.imageSmoothingQuality = 'high';
          srcCtx.drawImage(encCanvas, 0, 0, size, size);
        }
        try {
          const vf = new VideoFrame(src, { timestamp: Math.round(i * 1e6 / FPS), duration: Math.round(1e6 / FPS) });
          enc.encode(vf, { keyFrame: i % 60 === 0 });
          vf.close();
          i++;
        } catch (e) { failed = true; }
      },
      async finish(onProgress) {
        while (!failed && i < NFRAMES) {
          const before = i;
          this.step();
          if (i === before || i % 8 === 0) { onProgress(i / NFRAMES); await pause(); }
        }
        if (failed) return null;
        try {
          await enc.flush();
          enc.close();
          muxer.finalize();
          return new Blob([muxer.target.buffer], { type: 'video/mp4' });
        } catch (e) { return null; }
      },
      cancel() { failed = true; try { enc.close(); } catch (e) {} }
    };
  }

  // Ersatz für alte Browser: Aufnahme in Echtzeit
  function pickMime() {
    if (!window.MediaRecorder || !canvas.captureStream) return null;
    const list = ['video/mp4;codecs=avc1.42E01E', 'video/mp4;codecs=avc1', 'video/mp4',
                  'video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm'];
    for (const m of list) { try { if (MediaRecorder.isTypeSupported(m)) return m; } catch (e) {} }
    return '';
  }

  function startRecording(mime) {
    const chunks = [];
    const stream = canvas.captureStream(30);
    const opts = { videoBitsPerSecond: 2500000 };
    if (mime) opts.mimeType = mime;
    try { recorder = new MediaRecorder(stream, opts); }
    catch (e) { recorder = null; return false; }
    recorder.ondataavailable = e => { if (e.data && e.data.size) chunks.push(e.data); };
    recorder.onstop = () => {
      const type = (recorder && recorder.mimeType) || mime || 'video/webm';
      videoExt = type.includes('mp4') ? 'mp4' : 'webm';
      videoBlob = new Blob(chunks, { type: type.split(';')[0] });
      recorder = null;
      finish(true);
    };
    recorder.start(250);
    return true;
  }

  function stopRecorder(silent) {
    if (recorder && recorder.state !== 'inactive') {
      if (silent) recorder.onstop = null;
      recorder.stop();
    }
    if (silent) recorder = null;
  }

  function stopJob() { if (job) { job.cancel(); job = null; } }

  // ---------- Abspielen ----------
  async function play(record) {
    cancelAnimationFrame(rafId);
    const myRun = runId;
    replayBtn.hidden = true; saveBtn.hidden = true; shareBtn.hidden = true;
    pickBtn.classList.add('busy');
    let recording = false, cfg = null;
    if (record) {
      cfg = await pickEncoderConfig();
      if (myRun !== runId) return;
      if (cfg) job = createVideoJob(cfg);
      if (!job) { const m = pickMime(); if (m !== null) recording = startRecording(m); }
    }
    const myJob = job;
    setStatus('👀 Schau hin …');
    drawFrame(0);
    const t0 = performance.now();
    const step = async now => {
      if (myRun !== runId) return;
      const t = (now - t0) / 1000;
      drawFrame(Math.min(t, TOTAL));
      if (myJob) myJob.step();          // nebenbei ein Videobild erzeugen
      if (t < TOTAL) { rafId = requestAnimationFrame(step); return; }
      if (myJob) {
        const prog = p => setStatus('⏳ Video wird erstellt … ' + Math.round(p * 100) + ' %');
        let blob = await myJob.finish(prog);
        if (myRun !== runId) return;
        // Zu gross? Erst Bitrate senken, dann notfalls kleinere Auflösung
        const sizes = [W, 384, 320];
        for (let tries = 0; blob && blob.size > MAX_BYTES && tries < sizes.length; tries++) {
          const sz = sizes[tries];
          cfg = Object.assign({}, cfg, { width: sz, height: sz,
            bitrate: Math.max(300000, Math.round(cfg.bitrate * GOAL_BYTES / blob.size)) });
          job = createVideoJob(cfg);
          if (!job) break;
          const smaller = await job.finish(prog);
          if (myRun !== runId) return;
          if (!smaller) break;
          if (smaller.size < blob.size) blob = smaller;
        }
        job = null;
        if (blob) { videoBlob = blob; videoExt = 'mp4'; }
        finish(true);
      } else if (recording) {
        setTimeout(() => { if (myRun === runId) stopRecorder(false); }, 150);
      } else {
        finish(record);
      }
    };
    rafId = requestAnimationFrame(step);
  }

  function finish(triedVideo) {
    ready = true;
    pickBtn.classList.remove('busy');
    replayBtn.hidden = false;
    if (videoBlob) {
      saveBtn.hidden = false;
      try {
        const f = new File([videoBlob], 'schwiizmc.' + videoExt, { type: videoBlob.type });
        shareBtn.hidden = !(navigator.canShare && navigator.canShare({ files: [f] }));
      } catch (e) { shareBtn.hidden = true; }
      setStatus('✅ Fertig! Dein Video ist bereit.');
    } else {
      setStatus(triedVideo ? '✅ Fertig! Video speichern geht in diesem Browser leider nicht.' : '✅ Fertig!');
    }
  }

  // ---------- Ablauf ----------
  async function ensureTarget() {
    if (T) return;
    targetImg = await loadImage(TARGET_SRC);
    T = readPixels(targetImg, false, true);
  }

  function resetView() {
    runId++;
    cancelAnimationFrame(rafId);
    stopRecorder(true);
    stopJob();
    ready = false; anim = null; videoBlob = null;
    progress.hidden = true;
    replayBtn.hidden = true; saveBtn.hidden = true; shareBtn.hidden = true;
    pickBtn.classList.remove('busy');
    pickBtn.firstChild.textContent = '📷 Foto auswählen';
    ctx.fillStyle = '#0a1020';
    ctx.fillRect(0, 0, W, W);
    setStatus('');
  }

  function closeModal() {
    if (!ready) resetView();
    else { cancelAnimationFrame(rafId); stopRecorder(true); stopJob(); }
    modal.hidden = true;
    document.documentElement.style.overflow = '';
  }

  async function handleFile(input) {
    const f = input.files && input.files[0];
    input.value = '';
    if (!f) return;
    modal.hidden = false;
    document.documentElement.style.overflow = 'hidden';
    resetView();
    const myRun = runId;
    pickBtn.classList.add('busy');
    setStatus('Foto wird geladen …');
    let S, url;
    try {
      await ensureTarget();
      url = URL.createObjectURL(f);
      const im = await loadImage(url);
      S = readPixels(im, true);
    } catch (e) {
      pickBtn.classList.remove('busy');
      setStatus('Das Foto konnte nicht gelesen werden. Versuch es mit einem JPG oder PNG.');
      return;
    } finally {
      if (url) URL.revokeObjectURL(url);
    }
    if (myRun !== runId) return;
    showImage(S.canvas);
    bar.style.width = '0%';
    progress.hidden = false;
    await nextFrame();
    const assign = await computeAssignment(S, myRun);
    if (!assign || myRun !== runId) return;
    progress.hidden = true;
    anim = prepareAnim(S, assign);
    pickBtn.firstChild.textContent = '📷 Anderes Foto';
    play(true);
  }

  fileInput.addEventListener('change', () => handleFile(fileInput));
  $('morph-file-main').addEventListener('change', e => handleFile(e.target));
  $('morph-close').addEventListener('click', closeModal);
  modal.addEventListener('click', e => { if (e.target === modal) closeModal(); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && !modal.hidden) closeModal(); });
  replayBtn.addEventListener('click', () => play(false));

  saveBtn.addEventListener('click', () => {
    if (!videoBlob) return;
    const a = document.createElement('a');
    a.href = URL.createObjectURL(videoBlob);
    a.download = 'schwiizmc.' + videoExt;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 10000);
  });

  shareBtn.addEventListener('click', async () => {
    if (!videoBlob) return;
    const f = new File([videoBlob], 'schwiizmc.' + videoExt, { type: videoBlob.type });
    try { await navigator.share({ files: [f], title: 'SchwiizMC' }); } catch (e) {}
  });
})();
